package com.cognizant.loan.controller;import java.math.BigDecimal;import org.springframework.web.bind.annotation.*;@RestController public class LoanController{record Loan(String number,String type,BigDecimal loan,BigDecimal emi,int tenure){}@GetMapping("/loans/{number}")public Loan get(@PathVariable String number){return new Loan(number,"car",new BigDecimal("400000"),new BigDecimal("3258"),18);}}